}

// Handle empty partition map
if (partition_to_bucket.empty()) {
    throw std::runtime_error("No buckets available");
}

// Find the first partition point greater than hash
auto it = partition_to_bucket.upper_bound(hash);

// If hash exceeds all partition points, wrap to first bucket
if (it == partition_to_bucket.end()) {
    it = partition_to_bucket.begin();
}

// Return the bucket pointer
return it->second;

